using System;using System.IO;using SargasPC;
class ArchiveTests {static int n;static void Check(bool b){n++;if(!b)throw new Exception("Archive case "+n);}static void Main(string[] args){string[,] cases={{"normal.zip","Įrašų: 1"},{"renamed.dat","Įrašų: 1"},{"broken.zip","NEUŽBAIGTA"},{"fake.zip","NEUŽBAIGTA"},{"paths.zip","neįprastų kelių: 1"},{"nested.zip","vidinių archyvų: 1"},{"encrypted.zip","Šifruotų: 1"},{"ratio.zip","perspėjimų: 1"},{"method.zip","kitų metodų: 1"},{"zip64.zip","NEUŽBAIGTA"},{"boundary.zip","NEUŽBAIGTA"},{"count.zip","NEUŽBAIGTA"},{"large-count.zip","512 įrašų"},{"long-name.zip","NEUŽBAIGTA"},{"empty.zip","Įrašų: 0"}};for(int i=0;i<cases.GetLength(0);i++)using(var f=File.OpenRead(Path.Combine(args[0],cases[i,0]))){string r=ArchiveReview.Inspect(f,cases[i,0],()=>{});Check(r.Contains(cases[i,1]));Check(r.Contains("netikrintas")||r.Contains("NETIKRINTOS"));}using(var f=File.OpenRead(Path.Combine(args[0],"plain.txt")))Check(ArchiveReview.Inspect(f,"plain.txt",()=>{})=="");bool cancel=false;try{using(var f=File.OpenRead(Path.Combine(args[0],"normal.zip")))ArchiveReview.Inspect(f,"normal.zip",()=>{throw new OperationCanceledException();});}catch(OperationCanceledException){cancel=true;}Check(cancel);Check(ArchiveReview.Named("FILE.DOCX"));Check(!ArchiveReview.Named("file.exe"));string root=Path.Combine(Path.GetTempPath(),"sargas-archive-"+Guid.NewGuid().ToString("N"));try{var c=new Core(root);var w=c.Scan(Path.Combine(args[0],"normal.zip"));Check(w.Archive.Contains("Įrašų: 1"));string text=c.Describe(w,c.Database());Check(c.NotChecked==1&&text.Contains("NETIKRINTOS")&&w.Kind=="NONE");Check(c.Outcome(true).Contains("NEUŽBAIGTA"));}finally{if(Directory.Exists(root))Directory.Delete(root,true);}Console.WriteLine("PC ArchiveTests: "+n+" checks passed (metadata only; no extraction or real malware).");}}
